import com.android.SdkConstants;
import com.android.annotations.NonNull;
import com.android.tools.lint.detector.api.*;
import org.w3c.dom.Attr;
import org.w3c.dom.Element;

import java.util.*;

public class DuplicateIdDetector extends ResourceXmlDetector {
    private static final Implementation IMPL = new Implementation(
            DuplicateIdDetector.class,
            Scope.RESOURCE_FILE_SCOPE);

    public static final Issue ISSUE = Issue.create(
            "DuplicateIds",
            "Duplicate ids within a single layout",
            "Within a layout, id's should be unique since otherwise `findViewById()` can return an unexpected view.",
            Category.CORRECTNESS,
            7,
            Severity.ERROR,
            IMPL);

    private Map<String, List<Attr>> mIds;

    @Override
    public Collection<String> getApplicableAttributes() {
        return Collections.singletonList(SdkConstants.ATTR_ID);
    }

    @Override
    public void beforeCheckFile(XmlContext context) {
        mIds = new HashMap<>();
    }

    @Override
    public void visitAttribute(XmlContext context, Attr attribute) {
        String value = attribute.getValue();
        if (value == null || !value.startsWith("@+id/")) {
            return;
        }
        String id = value.substring(5);
        List<Attr> list = mIds.get(id);
        if (list == null) {
            list = new ArrayList<>();
            mIds.put(id, list);
        }
        list.add(attribute);
    }

    @Override
    public void afterCheckFile(XmlContext context) {
        for (Map.Entry<String, List<Attr>> entry : mIds.entrySet()) {
            List<Attr> list = entry.getValue();
            if (list.size() > 1) {
                String id = entry.getKey();
                String message = String.format(
                        "Duplicate id @+id/%1$s, already defined earlier in this layout",
                        id);
                for (Attr attr : list) {
                    context.report(ISSUE, attr, context.getValueLocation(attr), message);
                }
            }
        }
        mIds = null;
    }
}
```

